// Node.js TCP server and client using the built-in 'net' module
// Demonstrates: connection, data exchange, and four-way teardown

const net = require('net');

// ── TCP Server ────────────────────────────────────────────────
const server = net.createServer((socket) => {
  // This callback fires AFTER the three-way handshake completes.
  // The kernel handled SYN, SYN-ACK, ACK transparently.
  console.log(`Client connected: ${socket.remoteAddress}:${socket.remotePort}`);

  // socket is a full-duplex stream — data arrives in order, reliably
  socket.on('data', (chunk) => {
    const message = chunk.toString().trim();
    console.log(`Received: "${message}"`);

    // TCP guarantees this reply reaches the client in order
    socket.write(`Echo: ${message.toUpperCase()}\n`);
  });

  // 'end' fires when the remote side sends a FIN (half-close)
  socket.on('end', () => {
    console.log('Client sent FIN — connection half-closed');
  });

  // 'close' fires after the full four-way teardown completes
  socket.on('close', () => console.log('Connection fully closed'));

  socket.on('error', (err) => {
    // Common errors: ECONNRESET (peer sent RST), ETIMEDOUT (keepalive expired)
    console.error(`Socket error: ${err.code} - ${err.message}`);
  });
});

server.listen(9000, '127.0.0.1', () => {
  console.log('TCP server listening on 127.0.0.1:9000');

  // ── TCP Client ────────────────────────────────────────────────
  const client = net.createConnection(
    { port: 9000, host: '127.0.0.1' },
    () => {
      // Callback fires after handshake — kernel allocated local ephemeral port
      console.log(`Connected (local port: ${client.localPort})`);
      client.write('hello tcp\n');
    }
  );

  client.on('data', (chunk) => {
    console.log(`Server replied: "${chunk.toString().trim()}"`);
    // client.end() sends a FIN — initiates four-way teardown from client side.
    // The connection enters TIME_WAIT on this side for ~60s after close.
    client.end();
    server.close(); // stop accepting new connections
  });

  client.on('error', (err) => console.error(`Client error: ${err.code}`));
});

// Expected output:
// TCP server listening on 127.0.0.1:9000
// Connected (local port: 54321)     <- OS-assigned ephemeral port
// Client connected: 127.0.0.1:54321
// Received: "hello tcp"
// Server replied: "Echo: HELLO TCP"
// Client sent FIN — connection half-closed
// Connection fully closed

// Node.js UDP client and server using the 'dgram' module
// Demonstrates: fire-and-forget, message boundaries, no connection

const dgram = require('dgram');

// ── UDP Server ────────────────────────────────────────────────
const server = dgram.createSocket('udp4');

server.on('message', (msg, rinfo) => {
  // Each call to this handler is ONE complete datagram — message
  // boundaries are preserved. No framing needed.
  console.log(`UDP server received "${msg}" from ${rinfo.address}:${rinfo.port}`);

  // Send a reply — also fire-and-forget. No guarantee client receives it.
  const reply = Buffer.from(`Pong: ${msg}`);
  server.send(reply, rinfo.port, rinfo.address, (err) => {
    if (err) console.error('Send error:', err);
    // 'err' means the OS could not enqueue the send, NOT that it was
    // dropped — UDP has no delivery confirmation
  });
});

server.on('listening', () => {
  const addr = server.address();
  console.log(`UDP server listening on ${addr.address}:${addr.port}`);
});

server.on('error', (err) => {
  console.error('Server error:', err);
  server.close();
});

server.bind(41234);

// ── UDP Client ────────────────────────────────────────────────
// No connect() needed — UDP is connectionless.
// We create a socket, send directly, and listen for a response.
const client = dgram.createSocket('udp4');

client.on('message', (msg) => {
  console.log(`UDP client received: "${msg}"`);
  // No teardown — just stop listening
  client.close();
  server.close();
});

// Send after a brief delay to let server bind
setTimeout(() => {
  const message = Buffer.from('Ping');
  // There is NO handshake here. Datagram goes directly.
  client.send(message, 41234, '127.0.0.1', (err) => {
    if (err) console.error('Client send error:', err);
    // If server is down, this succeeds (OS enqueued it) but no reply comes
  });
}, 50);

// Expected output:
// UDP server listening on 0.0.0.0:41234
// UDP server received "Ping" from 127.0.0.1:XXXXX
// UDP client received: "Pong: Ping"

// If server was not running, client.send() would still succeed —
// UDP has no way to know the destination is unreachable until
// the OS returns an ICMP Port Unreachable, which may be suppressed.
